// GENERATED by npm run sync from the website's src/cms/layouts.ts. Change it there.
/**
 * 页面布局 (the owner, 2026-11-16, after Bell's `PageLayout` and `ZoneId`: 「这里还缺少了对于page的layout的添加，比如有landing
 * page layout， 还有homepagelayout 以及article 啊那些。 都要包含基本的header和footer那些， page里的内容是由不同的component组成
 * 的」): a page picks a layout, and each of its components stands in one of the layout's zones. Every layout is drawn
 * between the site's header and footer. The four built-in ones are here (drawn by render.tsx); a layout written in the
 * CMS is template markup (template.ts) with a `<Zone name="…" />` where each zone's components go. No React and no Node:
 * the CMS takes this file through its npm run sync.
 */
import { type L10n, pick } from "./model";
import { type FieldInfo, isElement, parseTemplate, type TNode } from "./template";

/** A zone: where a page's components stand. [full]: across the window (a banner); else in the site's container. */
export type Zone = { name: string; label: string; label_en: string; full?: boolean };

export type BuiltinLayout = {
  label: string;
  label_en: string;
  description: string;
  description_en: string;
  zones: Zone[];
  /** A breadcrumb under the header unless the page says otherwise. */
  breadcrumb: boolean;
  /** More room above and below the main zone (a home page, a landing page). */
  roomy?: boolean;
};

const MAIN: Zone = { name: "main", label: "主区", label_en: "Main" };
const HERO: Zone = { name: "hero", label: "横幅区", label_en: "Hero", full: true };

