export const DEFAULT_LAYOUT = "standard";

export const isBuiltinLayout = (name: string | undefined): name is keyof typeof LAYOUTS =>
  !!name && name in LAYOUTS;

/** A page's layout: its own, or for a page made before layouts, 首页 when it had the roomy spacing, else 标准. */
export const layoutOf = (p: { layout?: string; spacing?: string }) =>
  p.layout || (p.spacing === "roomy" ? "home" : DEFAULT_LAYOUT);

/** What a layout written in the CMS binds: the page's own words. */
export const LAYOUT_FIELDS: FieldInfo[] = [
  { name: "title", kind: "text" },
  { name: "description", kind: "text" },
];

/** The zones of a layout written in the CMS: its Zone elements' names, in order (none when it doesn't parse). */
export function zonesOfMarkup(markup: string): string[] {
  const out: string[] = [];
  const walk = (nodes: TNode[]) => {
    for (const n of nodes) {
      if (!isElement(n)) continue;
      if (n.tag === "Zone" && typeof n.attrs.name === "string" && !out.includes(n.attrs.name))
        out.push(n.attrs.name);
      walk(n.children);
    }
  };
  const { nodes, problems } = parseTemplate(markup);
  if (!problems.length) walk(nodes);
  return out;
}

/** The zone a component stands in when nothing says: the layout's first full zone for a banner, else main or the first. */
export function defaultZone(zones: string[], full: boolean, fullZones: string[] = []): string {
  if (full) {
    const banner = zones.find((z) => fullZones.includes(z));
    if (banner) return banner;
  }
  return zones.includes("main") ? "main" : (zones[0] ?? "main");
}

/** A link of a breadcrumb: a page's address and its title in the page's language. */
export type Crumb = { path: string; title: string };

/** The pages above [path] that exist, then the page itself: a breadcrumb's links, in [locale]. */
export function crumbsOf(pages: { path: string; title: L10n }[], path: string, locale: string): Crumb[] {
  const out: Crumb[] = [];
  const parts = path.split("/").filter(Boolean);
  for (let i = 0; i <= parts.length; i++) {
    const at = i === 0 ? "/" : `/${parts.slice(0, i).join("/")}/`;
    const page = pages.find((p) => p.path === at);
    if (page) out.push({ path: at, title: pick(page.title, locale) || at });
  }
  return out;
}
